// Round 3 — camper counter, balanced pressure.
//
// This player parks in the left third (x ~50-150) and holds fire until a burst,
// slam or spawn opens a window — 10-20x more shots land during those telegraphs
// than during plain movement. Answer: track a short ring of recent positions to
// lead a slam into where they actually are (not the lifetime heat cell, which is
// stale), and roll the punish so it isn't a metronome the player can re-learn.
export const meta = {
  name: 'Cistern I',
  rationale: 'You always dig into the same corner of the pool, so half the time I fill it before you climb out.',
  version: 1,
};

const MARCH_LEG = 34;
const MARCH_LOOK = 40;
const MARCH_EDGE = 34;
const CLOSE = 285;
const RING_RANGE = 150;
const SPAWN_EVERY = 420;
const SLAM_LEAD = 24;
const RECORD_EVERY = 10;
const RING_SIZE = 12; // 12 * 10 = 120 ticks of history, small memory

export function init() {
  return { lastSpawn: -999, lastAttack: -999, ring: [], ringI: 0 };
}

export function decide(view, mem) {
  const boss = view.boss;
  const player = view.player;
  const cd = boss.cooldowns;
  const aw = view.arena.w;
  const ah = view.arena.h;

  // Maintain short position ring.
  if (!mem.ring) mem.ring = [];
  if (view.tick % RECORD_EVERY === 0) {
    if (mem.ring.length < RING_SIZE) {
      mem.ring.push(player.x, player.y);
    } else {
      const idx = (mem.ringI % RING_SIZE) * 2;
      mem.ring[idx] = player.x;
      mem.ring[idx + 1] = player.y;
      mem.ringI = mem.ringI + 1;
    }
  }
  let cxSum = 0, cySum = 0, n = 0;
  for (let i = 0; i + 1 < mem.ring.length; i += 2) {
    cxSum += mem.ring[i];
    cySum += mem.ring[i + 1];
    n = n + 1;
  }
  const centroidX = n > 0 ? cxSum / n : player.x;
  const centroidY = n > 0 ? cySum / n : player.y;

  const dx = player.x - boss.x;
  const dy = player.y - boss.y;
  const dist = Math.sqrt(dx * dx + dy * dy);
  const angle = dist < 0.001 ? boss.facing : Math.atan2(dy, dx);

  const vx = typeof player.vx === 'number' && isFinite(player.vx) ? player.vx : 0;
  const vy = typeof player.vy === 'number' && isFinite(player.vy) ? player.vy : 0;

  // Pressure source 1: slam led by ring centroid + velocity, gated by rand so it
  // isn't a fixed beat, and never fired back-to-back without a quiet window.
  const quiet = view.tick - mem.lastAttack;
  if (cd.slam === 0 && quiet > 60 && dist < 330) {
    if (rand() < 0.5) {
      mem.lastAttack = view.tick;
      const tx = clamp(centroidX * 0.5 + player.x * 0.5 + vx * SLAM_LEAD, 0, aw);
      const ty = clamp(centroidY * 0.5 + player.y * 0.5 + vy * SLAM_LEAD, 0, ah);
      return { type: 'slam', x: tx, y: ty };
    }
  }

  // Pressure source 2: burst — ring at contact (unanswerable up close), cone at
  // range aimed at live player position, also rand-gated.
  if (cd.burst === 0 && quiet > 45) {
    if (rand() < 0.6) {
      mem.lastAttack = view.tick;
      return { type: 'burst', angle: angle, count: dist < RING_RANGE ? 8 : 5 };
    }
  }

  // Slow spawn cadence — bait them out of the left column by dropping the minion
  // center-right, forcing repositioning before the next punish.
  if (cd.spawn === 0 && view.tick - mem.lastSpawn > SPAWN_EVERY) {
    if (rand() < 0.5) {
      mem.lastSpawn = view.tick;
      const sx = clamp(aw * 0.65, 0, aw);
      const sy = clamp(centroidY, 0, ah);
      return { type: 'spawn', x: sx, y: sy };
    }
  }

  // Off-beat: hold working distance, march a square (straight legs, no idle rest).
  if (dist > CLOSE && dist > 0.001) {
    return { type: 'move', dx: dx / dist, dy: dy / dist };
  }
  if (dist < CLOSE - 90 && dist > 0.001) {
    return retreat(view, dx / dist, dy / dist);
  }
  return march(view);
}

function march(view) {
  const boss = view.boss;
  const leg = Math.floor(view.tick / MARCH_LEG) % 4;
  let dx = leg === 0 ? 1 : leg === 2 ? -1 : 0;
  let dy = leg === 1 ? 1 : leg === 3 ? -1 : 0;
  if (blocked(view, boss.x + dx * MARCH_LOOK, boss.y + dy * MARCH_LOOK)) {
    dx = -dx;
    dy = -dy;
  }
  if (blocked(view, boss.x + dx * MARCH_LOOK, boss.y + dy * MARCH_LOOK)) {
    const cx = view.arena.w / 2 - boss.x;
    const cy = view.arena.h / 2 - boss.y;
    const cmag = Math.sqrt(cx * cx + cy * cy);
    if (cmag > 0.001) return { type: 'move', dx: cx / cmag, dy: cy / cmag };
  }
  return { type: 'move', dx: dx, dy: dy };
}

function blocked(view, x, y) {
  return x < MARCH_EDGE || x > view.arena.w - MARCH_EDGE || y < MARCH_EDGE || y > view.arena.h - MARCH_EDGE;
}

function retreat(view, ux, uy) {
  const boss = view.boss;
  const dirs = [-ux, -uy, -uy, ux, uy, -ux];
  for (let i = 0; i < dirs.length; i = i + 2) {
    const cx = dirs[i];
    const cy = dirs[i + 1];
    if (!blocked(view, boss.x + cx * MARCH_LOOK, boss.y + cy * MARCH_LOOK)) {
      return { type: 'move', dx: cx, dy: cy };
    }
  }
  const cx = view.arena.w / 2 - boss.x;
  const cy = view.arena.h / 2 - boss.y;
  const cmag = Math.sqrt(cx * cx + cy * cy);
  if (cmag > 0.001) return { type: 'move', dx: cx / cmag, dy: cy / cmag };
  return { type: 'move', dx: 1, dy: 0 };
}

function clamp(v, lo, hi) {
  return v < lo ? lo : v > hi ? hi : v;
}

