events.source:
// Round 3 — camper punish. This player parks in the left third (x=0-200) and
// only fires during our burst/spawn/slam windows, never during plain movement.
// Three pressure sources: aggressive spawn cadence to deny their lane, a
// tracked-position slam/burst pair that leads their live position, and a full
// ring at contact. The open door: staying right of center (x>400) and moving
// keeps them outside spawn/slam range and off the ring — that lane still wins.
export const meta = {
  name: 'Sentinel II',
  rationale: 'You live in that left column and only shoot when I open a window — so I keep three windows open at once and put a minion right where you camp.',
  version: 2,
};

const MARCH_LEG = 34;
const MARCH_LOOK = 40;
const MARCH_EDGE = 34;

const SLAM_LEAD = 22;
const CLOSE = 260;
const RING_RANGE = 170;
const SPAWN_EVERY = 260;         // aggressive: spawn as often as cooldown allows
const LEFT_X = 130;               // hot-cell zone center, x=50-150
const LEFT_Y = 400;               // hot-cell zone center, y=250-550 avg

export function init() {
  return { lastSpawn: -999, ring: [], ringIdx: 0, phase: 0 };
}

export function decide(view, mem) {
  const boss = view.boss;
  const player = view.player;
  const cd = boss.cooldowns;
  const aw = view.arena.w;
  const ah = view.arena.h;

  // Track player's recent position ring (centroid over ~last 60 samples).
  if (view.tick % 10 === 0) {
    if (!mem.ring) mem.ring = [];
    mem.ring[mem.ringIdx % 60] = { x: player.x, y: player.y };
    mem.ringIdx = (mem.ringIdx || 0) + 1;
  }
  let cxSum = 0, cySum = 0, cCount = 0;
  if (mem.ring && mem.ring.length) {
    for (let i = 0; i < mem.ring.length; i++) {
      const p = mem.ring[i];
      if (p) { cxSum += p.x; cySum += p.y; cCount++; }
    }
  }
  const centroidX = cCount > 0 ? cxSum / cCount : player.x;
  const centroidY = cCount > 0 ? cySum / cCount : player.y;

  const dx = player.x - boss.x;
  const dy = player.y - boss.y;
  const dist = Math.sqrt(dx * dx + dy * dy);
  const angle = dist < 0.001 ? boss.facing : Math.atan2(dy, dx);

  const vx = typeof player.vx === 'number' && isFinite(player.vx) ? player.vx : 0;
  const vy = typeof player.vy === 'number' && isFinite(player.vy) ? player.vy : 0;

  // Contact ring — unanswerable at close range, per the engine notes.
  if (dist < RING_RANGE && cd.burst === 0) {
    return { type: 'burst', angle: angle, count: 8 };
  }

  // Spawn as often as possible, anchored on the hot left-third zone, but only
  // if the player is actually living there recently (share check via centroid).
  if (cd.spawn === 0 && view.tick - mem.lastSpawn > SPAWN_EVERY) {
    mem.lastSpawn = view.tick;
    // If player is currently left-biased, plant minion there; otherwise
    // plant it center-right to bait them out of the corner.
    const targetX = centroidX < aw * 0.4 ? LEFT_X : aw * 0.55;
    const targetY = centroidX < aw * 0.4 ? clamp(centroidY, 100, ah - 100) : LEFT_Y;
    return { type: 'spawn', x: clamp(targetX, 0, aw), y: clamp(targetY, 0, ah) };
  }

  // Slam led by live position + velocity, biased toward the left hot zone,
  // but capped so it never targets past ~330px travel (guaranteed-miss zone).
  if (cd.slam === 0) {
    const leadX = clamp(player.x + vx * SLAM_LEAD, 0, aw);
    const leadY = clamp(player.y + vy * SLAM_LEAD, 0, ah);
    const tdx = leadX - boss.x;
    const tdy = leadY - boss.y;
    const tdist = Math.sqrt(tdx * tdx + tdy * tdy);
    if (tdist < 330) {
      return { type: 'slam', x: leadX, y: leadY };
    }
  }

  // Burst pressure at range, off cooldown, varied count via rand to avoid a
  // readable metronome (the analyst noted they read fixed counts/timing).
  if (cd.burst === 0) {
    const r = rand();
    const count = r < 0.4 ? 5 : r < 0.75 ? 3 : 8;
    return { type: 'burst', angle: angle, count: count };
  }

  // Close the gap, but leave the right side (x>400, away from the hot zone)
  // as the escape lane — don't chase relentlessly if they're already there.
  const playerIsRight = player.x > aw * 0.5;
  if (dist > CLOSE && dist > 0.001 && !(playerIsRight && dist > CLOSE * 1.4)) {
    return { type: 'move', dx: dx / dist, dy: dy / dist };
  }
  if (dist < CLOSE - 80 && dist > 0.001) {
    return retreat(view, dx / dist, dy / dist);
  }

  return march(view);
}

function march(view) {
  const boss = view.boss;
  const leg = Math.floor(view.tick / MARCH_LEG) % 4;
  let dx = leg === 0 ? 1 : leg === 2 ? -1 : 0;
  let dy = leg === 1 ? 1 : leg === 3 ? -1 : 0;
  if (blocked(view, boss.x + dx * MARCH_LOOK, boss.y + dy * MARCH_LOOK)) {
    dx = -dx;
    dy = -dy;
  }
  if (blocked(view, boss.x + dx * MARCH_LOOK, boss.y + dy * MARCH_LOOK)) {
    const cx = view.arena.w / 2 - boss.x;
    const cy = view.arena.h / 2 - boss.y;
    const cmag = Math.sqrt(cx * cx + cy * cy);
    if (cmag > 0.001) return { type: 'move', dx: cx / cmag, dy: cy / cmag };
  }
  return { type: 'move', dx: dx, dy: dy };
}

function blocked(view, x, y) {
  return x < MARCH_EDGE || x > view.arena.w - MARCH_EDGE || y < MARCH_EDGE || y > view.arena.h - MARCH_EDGE;
}

function retreat(view, ux, uy) {
  const boss = view.boss;
  const dirs = [-ux, -uy, -uy, ux, uy, -ux];
  for (let i = 0; i < dirs.length; i = i + 2) {
    const cx = dirs[i];
    const cy = dirs[i + 1];
