events.source:
// Round 3 — SENTRY III. One pressure source: burst, fired every time it's ready,
// led onto where the player is moving (velocity lead + a short position ring),
// biased toward their known left-side habit. No slam, no spawn. When the player
// closes to contact we do not punish it — we open range instead, because a cone
// at contact is a free dodge and this file only ever throws cones.
export const meta = {
  name: 'Sentry III',
  rationale: 'You camp the left wall and wait for my openings, so I stopped giving you one to wait for.',
  version: 3,
};

const HOLD = 320;        // preferred shooting range
const OPEN = 380;        // if closer than this, back off instead of shooting
const MARCH_LEG = 34;     // straight-leg patrol length (ticks) — stays unhittable-by-curve-free
const MARCH_LOOK = 40;
const MARCH_EDGE = 34;
const RING_SIZE = 48;     // ~ ticks of position history for centroid lead
const RING_EVERY = 10;

export function init() {
  return { ring: [], ringTick: -999, phase: 0 };
}

export function decide(view, mem) {
  const boss = view.boss;
  const player = view.player;
  const cd = boss.cooldowns;
  const aw = view.arena.w;
  const ah = view.arena.h;

  // maintain a short ring of recent player positions
  if (view.tick - mem.ringTick >= RING_EVERY) {
    mem.ringTick = view.tick;
    if (!Array.isArray(mem.ring)) mem.ring = [];
    mem.ring.push(player.x, player.y);
    if (mem.ring.length > RING_SIZE * 2) {
      mem.ring.splice(0, mem.ring.length - RING_SIZE * 2);
    }
  }

  let cx = player.x;
  let cy = player.y;
  const ring = mem.ring;
  if (Array.isArray(ring) && ring.length >= 2) {
    let sx = 0, sy = 0, n = 0;
    for (let i = 0; i < ring.length; i += 2) {
      sx += ring[i];
      sy += ring[i + 1];
      n++;
    }
    if (n > 0) {
      cx = sx / n;
      cy = sy / n;
    }
  }

  const vx = typeof player.vx === 'number' && isFinite(player.vx) ? player.vx : 0;
  const vy = typeof player.vy === 'number' && isFinite(player.vy) ? player.vy : 0;

  // lead target: blend centroid (habit) with live velocity lead (where they're going)
  const LEAD = 18;
  let tx = cx * 0.4 + player.x * 0.6 + vx * LEAD;
  let ty = cy * 0.4 + player.y * 0.6 + vy * LEAD;
  tx = clamp(tx, 0, aw);
  ty = clamp(ty, 0, ah);

  const dx = player.x - boss.x;
  const dy = player.y - boss.y;
  const dist = Math.sqrt(dx * dx + dy * dy);

  const adx = tx - boss.x;
  const ady = ty - boss.y;
  const adist = Math.sqrt(adx * adx + ady * ady);
  const angle = adist < 0.001 ? boss.facing : Math.atan2(ady, adx);

  // The single pressure source: burst, every time it's off cooldown, no exceptions,
  // never a ring (never rewards contact) — a wide cone instead.
  if (cd.burst === 0) {
    // roll count per use to keep the panel bot in the fair band rather than a fixed duty cycle
    const r = rand();
    const count = r < 0.5 ? 5 : (r < 0.85 ? 8 : 3);
    return { type: 'burst', angle: angle, count: count };
  }

  // Never punish contact: if the player is close, open range instead of standing.
  if (dist < OPEN) {
    return retreat(view, dist > 0.001 ? dx / dist : 1, dist > 0.001 ? dy / dist : 0);
  }

  // Otherwise hold near preferred range or patrol.
  if (dist > HOLD) {
    return { type: 'move', dx: dx / (dist || 1), dy: dy / (dist || 1) };
  }

  return march(view);
}

function march(view) {
  const boss = view.boss;
  const leg = Math.floor(view.tick / MARCH_LEG) % 4;
  let dx = leg === 0 ? 1 : leg === 2 ? -1 : 0;
  let dy = leg === 1 ? 1 : leg === 3 ? -1 : 0;
  if (blocked(view, boss.x + dx * MARCH_LOOK, boss.y + dy * MARCH_LOOK)) {
    dx = -dx;
    dy = -dy;
  }
  if (blocked(view, boss.x + dx * MARCH_LOOK, boss.y + dy * MARCH_LOOK)) {
    const cxv = view.arena.w / 2 - boss.x;
    const cyv = view.arena.h / 2 - boss.y;
    const cmag = Math.sqrt(cxv * cxv + cyv * cyv);
    if (cmag > 0.001) return { type: 'move', dx: cxv / cmag, dy: cyv / cmag };
  }
  return { type: 'move', dx: dx, dy: dy };
}

function blocked(view, x, y) {
  return x < MARCH_EDGE || x > view.arena.w - MARCH_EDGE || y < MARCH_EDGE || y > view.arena.h - MARCH_EDGE;
}

function retreat(view, ux, uy) {
  const boss = view.boss;
  const dirs = [-ux, -uy, -uy, ux, uy, -ux];
  for (let i = 0; i < dirs.length; i += 2) {
    const cxv = dirs[i];
    const cyv = dirs[i + 1];
    if (!blocked(view, boss.x + cxv * MARCH_LOOK, boss.y + cyv * MARCH_LOOK)) {
      return { type: 'move', dx: cxv, dy: cyv };
    }
  }
  const cxv = view.arena.w / 2 - boss.x;
  const cyv = view.arena.h / 2 - boss.y;
  const cmag = Math.sqrt(cxv * cxv + cyv * cyv);
  if (cmag > 0.001) return { type: 'move', dx: cxv / cmag, dy: cyv / cmag };
  return { type: 'move', dx: 1, dy: 0 };
}

function clamp(v, lo, hi) {
  return v < lo ? lo : v > hi ? hi : v;
}

